/bin/zsh -lc "cd /var/tmp/loop-bench/runs/2780fbadb1ea/workspace/target && cat > src/transport/ws/listSessionsLimit.test.ts <<'EOF'
import {validateMessage} from './validation.js';

describe('list_sessions limit [spec: specs/hal-engine-conversation-list/spec.md#39]', () => {
  it('preserves non-negative integer limits and rejects malformed limits', () => {
    for (const limit of [-1, 1.5, '10', null, true, NaN, Infinity]) {
      expect(validateMessage({type: 'list_sessions', limit})).toEqual({
        valid: false,
        error: expect.stringContaining('limit'),
      });
    }
    for (const limit of [0, 10, 201]) {
      expect(validateMessage({type: 'list_sessions', limit, userId: 'another-user'})).toEqual({
        valid: true,
        data: {type: 'list_sessions', limit},
      });
    }
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsLimit.test.ts --runInBand"
